void light_pcapng_close(light_pcapng_t *pcapng)
{
        DCHECK_NULLP(pcapng, return);

        light_pcapng_release(pcapng->pcapng);
        pcapng->pcapng = NULL;
        if (pcapng->file != NULL)
        {
                light_flush(pcapng->file);
                light_close(pcapng->file);
        }
        light_free_file_info(pcapng->file_info);
        free(pcapng);
}

